(() => {
  'use strict';

  const $ = (id) => document.getElementById(id);
  const SESSION_KEY = 'reserve_cadre_stage4_2_session';
  const SYNC_INTERVAL_MS = 30000;
  const PDFJS_URL = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';
  const PDFJS_WORKER = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';

  const state = {
    token: '', user: null, packages: [], adminOverview: [],
    adminCatalog: { packages: [], learners: [], assignments: [] },
    activePackage: null, activeLesson: null, adminTab: 'people',
    previewMode: false, tracker: null, quiz: null,
    youtubePlayers: new Map(), youtubeObserver: null, pdfObserver: null, pdfJsPromise: null
  };

  const escapeHtml = (v = '') => String(v).replace(/[&<>'"]/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));
  const n = (v) => Number.isFinite(Number(v)) ? Number(v) : 0;
  const deepClone = (v) => JSON.parse(JSON.stringify(v || {}));

  function formatSeconds(seconds = 0) {
    const s = Math.max(0, Math.floor(n(seconds)));
    const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), sec = s % 60;
    if (h) return `${h}時${String(m).padStart(2,'0')}分`;
    if (m) return `${m}分${String(sec).padStart(2,'0')}秒`;
    return `${sec}秒`;
  }
  function formatDateTime(value) {
    const t = String(value || '').trim(); if (!t) return '—';
    if (/^\d{4}\/\d{2}\/\d{2}/.test(t)) return t.slice(0,16);
    const d = new Date(t); return Number.isNaN(d.getTime()) ? t : new Intl.DateTimeFormat('zh-TW',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(d);
  }
  function statusLabel(s){ return s==='complete'?'已完成':s==='in_progress'?'進行中':'未開始'; }
  function statusTag(s){ const c=s==='complete'?'tag--success':s==='in_progress'?'tag--warning':'tag--muted'; return `<span class="tag ${c}">${statusLabel(s)}</span>`; }
  function boolTag(done,text){ return `<span class="criteria-item ${done?'is-pass':''}">${done?'✓':'○'} ${escapeHtml(text)}</span>`; }
  function setModeBadge(mode,text){ const e=$('modeBadge'); e.className=`status-badge status-badge--${mode}`; e.textContent=text; }
  function showToast(msg){ const e=$('toast');e.textContent=msg;e.hidden=false;clearTimeout(showToast.t);showToast.t=setTimeout(()=>e.hidden=true,2800); }
  function showLoginError(msg){$('loginMessage').textContent=msg;$('loginMessage').hidden=false;}
  function setLoginLoading(v){const b=$('loginButton');b.disabled=v;b.classList.toggle('is-loading',v);b.textContent=v?'登入中…':'登入';}
  function saveSession(){if(state.token)sessionStorage.setItem(SESSION_KEY,JSON.stringify({token:state.token}));}
  function clearSession(){sessionStorage.removeItem(SESSION_KEY);}

  function packageSummary(pkg){
    if(Number.isFinite(Number(pkg.requiredTotal))&&Number.isFinite(Number(pkg.requiredDone))) return {done:n(pkg.requiredDone),total:n(pkg.requiredTotal),percent:n(pkg.percent),status:pkg.status||'not_started'};
    const req=(pkg.lessons||[]).filter(l=>l.required!==false), done=req.filter(l=>l.status==='complete').length, total=req.length;
    const percent=total?Math.round(done*100/total):0;
    return {done,total,percent,status:total&&done===total?'complete':done||req.some(l=>l.status==='in_progress')?'in_progress':'not_started'};
  }
  function contentTypes(l){const m={VIDEO:'影片',PDF:'PDF',TEXT:'文字',QUIZ:'測驗'};return [...new Set((l.contents||[]).map(x=>String(x.type||'').toUpperCase()))].filter(Boolean).map(x=>m[x]||x).join('＋')||'教材';}
  function youtubeId(url){
    const raw=String(url||'').trim(); if(!raw)return '';
    try{const u=new URL(raw);let id='';if(u.hostname.includes('youtu.be'))id=u.pathname.split('/').filter(Boolean)[0]||'';else if(u.searchParams.get('v'))id=u.searchParams.get('v')||'';else{const p=u.pathname.split('/').filter(Boolean),i=p.findIndex(x=>['embed','shorts','live'].includes(x));if(i>=0)id=p[i+1]||'';}return /^[\w-]{6,}$/.test(id)?id:'';}catch{return '';}
  }
  function drivePreviewUrl(url){const raw=String(url||'').trim(),m=raw.match(/drive\.google\.com\/(?:file\/d\/|open\?id=)([-\w]+)/i);return m?`https://drive.google.com/file/d/${m[1]}/preview`:raw;}
  function isDriveUrl(url){return /drive\.google\.com/i.test(String(url||''));}

  async function checkHealth(){if(!window.LearningApi||!window.LearningApi.configured()){setModeBadge('offline','尚未設定');return false;}try{const d=await window.LearningApi.request('health',{});setModeBadge(d&&d.ok?'online':'offline',d&&d.ok?'後端正常':'資料異常');return !!(d&&d.ok);}catch{setModeBadge('offline','連線異常');return false;}}
  async function login(employeeId,password){const d=await window.LearningApi.request('login',{employeeId,password});state.token=d.sessionToken;saveSession();await loadBootstrap();}
  async function loadBootstrap(){const d=await window.LearningApi.request('bootstrap',{},state.token);state.user=d.user||null;if(!state.user)throw new Error('無法取得登入資料。');if(d.mode==='admin'){state.adminOverview=Array.isArray(d.overview)?d.overview:[];state.adminCatalog=d.catalog||{packages:[],learners:[],assignments:[]};state.packages=[];}else{state.packages=Array.isArray(d.packages)?d.packages:[];state.adminOverview=[];state.adminCatalog={packages:[],learners:[],assignments:[]};}renderDashboard();}
  async function restoreSession(){let s;try{s=JSON.parse(sessionStorage.getItem(SESSION_KEY)||'null');}catch{}if(!s||!s.token)return false;state.token=s.token;try{await loadBootstrap();return true;}catch{state.token='';clearSession();return false;}}

  function renderDashboard(){
    $('loginView').hidden=true;$('dashboardView').hidden=false;$('lessonPage').hidden=true;
    $('userName').textContent=state.user.name||'—';$('userRole').textContent=state.user.role||'—';$('userMeta').textContent=`${state.user.employeeId||'—'}｜${state.user.area||'—'}｜${state.user.store||'—'}`;
    if(state.user.roleKey==='admin'){$('studentDashboard').hidden=true;$('adminDashboard').hidden=false;renderAdmin();}else{$('studentDashboard').hidden=false;$('adminDashboard').hidden=true;renderStudent();}
  }

  function renderStudent(){let total=0,done=0;state.packages.forEach(p=>{const s=packageSummary(p);total+=s.total;done+=s.done;});const complete=state.packages.filter(p=>packageSummary(p).status==='complete').length;$('studentSummary').innerHTML=`<article class="summary-card"><span>母課程</span><strong>${state.packages.length}</strong></article><article class="summary-card"><span>必修完成</span><strong>${done}/${total}</strong></article><article class="summary-card"><span>母課程完成</span><strong>${complete}/${state.packages.length}</strong></article>`;$('packageList').innerHTML=state.packages.length?state.packages.map(renderPackageCard).join(''):'<div class="empty-state"><h3>目前沒有指派課程</h3></div>';bindStudentPackageEvents();renderStudentRecords();}
  function renderPackageCard(pkg){const s=packageSummary(pkg),ls=pkg.lessons||[],next=ls.find(l=>l.status!=='complete')||ls[0];const rows=ls.map((l,i)=>`<div class="lesson-row ${l.status==='complete'?'is-complete':''}"><div class="lesson-number">${l.status==='complete'?'✓':i+1}</div><div class="lesson-info"><strong>${escapeHtml(l.title)}</strong><small>${escapeHtml(contentTypes(l))}${n(l.videoSeconds)+n(l.pdfSeconds)>0?`｜累積 ${formatSeconds(n(l.videoSeconds)+n(l.pdfSeconds))}`:''}</small></div><div class="lesson-status">${statusTag(l.status)}<button class="course-open-button" type="button" data-open-lesson="${escapeHtml(l.id)}" data-package-id="${escapeHtml(pkg.id)}">${l.status==='not_started'?'開始':'查看'}</button></div></div>`).join('');return `<article class="package-card"><div class="package-header"><div class="package-topline"><div><p class="step-label">母課程</p><h3 class="package-title">${escapeHtml(pkg.title)}</h3><p class="package-meta">${escapeHtml(pkg.description||'')}</p></div>${statusTag(s.status)}</div><div class="progress-line"><span style="width:${s.percent}%"></span></div><div class="progress-meta"><span>${s.done} / ${s.total} 個必修子課程完成</span><strong>${s.percent}%</strong></div><div class="package-actions"><button class="secondary-button" type="button" data-toggle-package="${escapeHtml(pkg.id)}">展開子課程</button>${next?`<button class="primary-button" type="button" data-open-lesson="${escapeHtml(next.id)}" data-package-id="${escapeHtml(pkg.id)}">${s.status==='complete'?'再次查看':'繼續學習'}</button>`:''}</div></div><div class="lesson-list" data-package-lessons="${escapeHtml(pkg.id)}" hidden>${rows}</div></article>`;}
  function bindStudentPackageEvents(){document.querySelectorAll('[data-toggle-package]').forEach(b=>b.onclick=()=>{const x=document.querySelector(`[data-package-lessons="${CSS.escape(b.dataset.togglePackage)}"]`);if(x){x.hidden=!x.hidden;b.textContent=x.hidden?'展開子課程':'收合子課程';}});document.querySelectorAll('[data-open-lesson]').forEach(b=>b.onclick=()=>openLesson(b.dataset.packageId,b.dataset.openLesson));}
  function renderStudentRecords(){const a=[];state.packages.forEach(p=>(p.lessons||[]).forEach(l=>a.push({p,l})));$('studentRecordsList').innerHTML=a.length?a.map(({p,l})=>`<article class="record-card"><div class="record-card__top"><div><strong>${escapeHtml(l.title)}</strong><p class="package-meta">${escapeHtml(p.title)}</p></div>${statusTag(l.status)}</div><div class="record-grid"><div><span>影片時數</span><strong>${n(l.videoSeconds)?formatSeconds(l.videoSeconds):'—'}</strong></div><div><span>PDF時數</span><strong>${n(l.pdfSeconds)?formatSeconds(l.pdfSeconds):'—'}</strong></div><div><span>測驗分數</span><strong>${l.score==null?'—':`${l.score} 分`}</strong></div><div><span>完成時間</span><strong>${formatDateTime(l.completedAt)}</strong></div></div></article>`).join(''):'<div class="empty-state"><h3>目前沒有學習紀錄</h3></div>';}
  function findLesson(packageId,lessonId){const pkg=state.packages.find(x=>x.id===packageId);return {pkg,lesson:pkg&&(pkg.lessons||[]).find(x=>x.id===lessonId)};}
  function refreshActiveLesson(){if(!state.activePackage||!state.activeLesson||state.previewMode)return;const f=findLesson(state.activePackage.id,state.activeLesson.id);if(f.pkg&&f.lesson){state.activePackage=f.pkg;state.activeLesson=f.lesson;}}

  async function openLesson(packageId,lessonId){let {pkg,lesson}=findLesson(packageId,lessonId);if(!pkg||!lesson)return;if(lesson.status==='not_started'){try{const ps=await window.LearningApi.request('saveProgress',{lessonId:lesson.id,contentProgress:lesson.contentProgress||{}},state.token);state.packages=Array.isArray(ps)?ps:state.packages;({pkg,lesson}=findLesson(packageId,lessonId));renderStudent();}catch(e){showToast(e.message||'無法建立開始紀錄');}}state.previewMode=false;state.activePackage=pkg;state.activeLesson=lesson;state.quiz=null;startTracker();renderLessonPage();}
  function openAdminPreview(pkg){if(!pkg)return;const lesson=(pkg.lessons||[]).find(l=>l.enabled!==false);if(!lesson){showToast('此課程尚未建立可預覽的子課程');return;}state.previewMode=true;state.activePackage=pkg;state.activeLesson={...lesson,status:'not_started',contentProgress:{},criteria:previewCriteria(lesson)};state.quiz=null;renderLessonPage();}
  function previewCriteria(l){return {videoRequired:l.videoPassPercent!=null,videoPassed:false,videoPercent:0,pdfRequired:!!l.pdfConfirmRequired,pdfPassed:false,quizRequired:l.quizPassScore!=null,quizPassed:false,allPassed:false};}
  function buildCriteria(l){const c=l.criteria||{};const a=[];if(c.videoRequired)a.push(boolTag(!!c.videoPassed,`影片 ${Math.min(100,Math.round(n(c.videoPercent)))}% / ${n(l.videoPassPercent)}%`));if(c.pdfRequired)a.push(boolTag(!!c.pdfPassed,'PDF 完成確認'));if(c.quizRequired)a.push(boolTag(!!c.quizPassed,`測驗 ${l.score==null?'—':n(l.score)} / ${n(l.quizPassScore)}分`));if(!a.length)a.push(boolTag(true,'開啟教材後可完成'));return `<div class="criteria-panel"><strong>通過條件</strong><div class="criteria-list">${a.join('')}</div></div>`;}
  function renderLessonPage(){const p=state.activePackage,l=state.activeLesson;if(!p||!l)return;$('studentDashboard').hidden=true;$('adminDashboard').hidden=true;$('lessonPage').hidden=false;$('lessonPackageName').textContent=p.title;$('lessonTitle').textContent=l.title;$('lessonMeta').innerHTML=(state.previewMode?'<div class="preview-banner">學員視角預覽｜不會寫入任何學習紀錄</div>':'')+`<span class="tag">${escapeHtml(contentTypes(l))}</span><span class="tag ${l.required?'tag--warning':'tag--muted'}">${l.required?'必修':'選修'}</span>`;$('lessonContent').innerHTML=buildCriteria(l)+((l.contents||[]).filter(x=>x.enabled!==false).map(renderContentBlock).join('')||'<div class="content-placeholder">尚未設定教材</div>');$('completeLessonButton').hidden=state.previewMode;$('completeLessonButton').disabled=l.status==='complete';$('completeLessonButton').textContent=l.status==='complete'?'已完成':'完成此子課程';bindLessonContentEvents();initLazyMedia();window.scrollTo({top:0,behavior:'auto'});}
  function contentProgress(item){const p=(state.tracker?state.tracker.contentProgress:(state.activeLesson&&state.activeLesson.contentProgress))||{};return p[item.id]||{};}
  function renderContentBlock(item){const type=String(item.type||'').toUpperCase(),title=escapeHtml(item.title||'教材'),url=String(item.url||'').trim(),cp=contentProgress(item);if(type==='TEXT')return `<article class="content-block"><h3>${title}</h3><p>${escapeHtml(item.text||'')}</p></article>`;if(type==='VIDEO'){const id=youtubeId(url);if(!id)return `<article class="content-block"><h3>${title}</h3><div class="content-placeholder">影片連結格式不正確</div></article>`;return `<article class="content-block video-content" data-content-id="${escapeHtml(item.id)}" data-video-url="${escapeHtml(url)}"><h3>${title}</h3><div class="media-lazy-shell"><div class="media-lazy-placeholder video-player" data-youtube-id="${escapeHtml(id)}" data-content-id="${escapeHtml(item.id)}" data-video-url="${escapeHtml(url)}"><div><strong>影片尚未載入</strong><span>滑到此處才會載入播放器</span></div></div></div><div class="pdf-status-line"><span>觀看：<strong data-video-time="${escapeHtml(item.id)}">${formatSeconds(cp.seconds||0)}</strong></span></div></article>`;}if(type==='PDF'){if(!url)return `<article class="content-block"><h3>${title}</h3><div class="content-placeholder">PDF 尚未設定</div></article>`;return `<article class="content-block pdf-content" data-content-id="${escapeHtml(item.id)}" data-pdf-url="${escapeHtml(url)}"><h3>${title}</h3><div class="pdf-viewer" data-pdf-viewer="${escapeHtml(item.id)}"><div class="media-lazy-placeholder"><div><strong>PDF 尚未載入</strong><span>滑到此處才會載入教材</span></div></div></div><div class="pdf-status-line"><span>閱讀：<strong data-pdf-time="${escapeHtml(item.id)}">${formatSeconds(cp.seconds||0)}</strong></span>${cp.maxPage?`<span>最高頁：<strong>${n(cp.maxPage)}${cp.pages?` / ${n(cp.pages)}`:''}</strong></span>`:''}</div><div class="content-actions"><a class="content-link" href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer">另開 PDF</a>${state.activeLesson&&state.activeLesson.pdfConfirmRequired&&!cp.confirmed?`<button class="secondary-button pdf-confirm-button" type="button" data-pdf-confirm="${escapeHtml(item.id)}">確認已閱讀</button>`:boolTag(!!cp.confirmed,'已確認閱讀')}</div></article>`;}if(type==='QUIZ')return `<article class="content-block quiz-block"><h3>${title}</h3><div id="quizArea">${state.previewMode?'<div class="content-placeholder">測驗預覽：正式學員可在此作答</div>':'<button class="secondary-button quiz-load-button" type="button">開始測驗</button>'}</div></article>`;return '';}
  function bindLessonContentEvents(){document.querySelectorAll('.pdf-confirm-button').forEach(b=>b.onclick=()=>confirmPdf(b.dataset.pdfConfirm));document.querySelectorAll('.quiz-load-button').forEach(b=>b.onclick=loadQuiz);}

  function activePage(){return document.visibilityState==='visible'&&document.hasFocus()&&!$('lessonPage').hidden&&!state.previewMode;}
  function startTracker(){stopTracker(false);const l=state.activeLesson;state.tracker={lessonId:l.id,contentProgress:deepClone(l.contentProgress||{}),playing:new Set(),visiblePdfs:new Set(),dirty:false,lastSync:Date.now(),timer:setInterval(tickTracker,1000)};}
  function ensureContentProgress(id,type){if(!state.tracker)return null;const p=state.tracker.contentProgress[id]||(state.tracker.contentProgress[id]={type,seconds:0});p.type=type;p.seconds=n(p.seconds);return p;}
  function tickTracker(){const t=state.tracker;if(!t||!activePage())return;t.playing.forEach(id=>{const p=ensureContentProgress(id,'VIDEO');p.seconds+=1;t.dirty=true;const e=document.querySelector(`[data-video-time="${CSS.escape(id)}"]`);if(e)e.textContent=formatSeconds(p.seconds);});t.visiblePdfs.forEach(id=>{const p=ensureContentProgress(id,'PDF');p.seconds+=1;t.dirty=true;const e=document.querySelector(`[data-pdf-time="${CSS.escape(id)}"]`);if(e)e.textContent=formatSeconds(p.seconds);});if(t.dirty&&Date.now()-t.lastSync>=SYNC_INTERVAL_MS)flushProgress(false);}
  async function flushProgress(showError=true){const t=state.tracker;if(!t||!t.dirty||state.previewMode)return;const payload={lessonId:t.lessonId,contentProgress:t.contentProgress};t.dirty=false;t.lastSync=Date.now();try{const ps=await window.LearningApi.request('saveProgress',payload,state.token);state.packages=Array.isArray(ps)?ps:state.packages;refreshActiveLesson();}catch(e){t.dirty=true;if(showError)showToast(e.message||'學習紀錄同步失敗');}}
  function stopTracker(flush=true){if(state.tracker&&state.tracker.timer)clearInterval(state.tracker.timer);if(flush&&state.tracker&&state.tracker.dirty)flushProgress(false);destroyMedia();state.tracker=null;}

  function destroyMedia(){if(state.youtubeObserver)state.youtubeObserver.disconnect();if(state.pdfObserver)state.pdfObserver.disconnect();state.youtubeObserver=null;state.pdfObserver=null;state.youtubePlayers.forEach(p=>{try{p.destroy();}catch{}});state.youtubePlayers.clear();}
  function initLazyMedia(){destroyMedia();initLazyYoutube();initLazyPdfVisibility();}
  function initLazyYoutube(){const nodes=[...document.querySelectorAll('.video-player[data-youtube-id]')];if(!nodes.length)return;if(location.protocol==='file:'){nodes.forEach(showLocalYoutubeFallback);return;}state.youtubeObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){state.youtubeObserver.unobserve(e.target);mountYoutube(e.target);}}),{rootMargin:'320px 0px'});nodes.forEach(n=>state.youtubeObserver.observe(n));}
  function showLocalYoutubeFallback(node){node.className='media-fallback';node.innerHTML=`<div><strong>本機測試不載入 YouTube</strong><p>直接雙擊 index.html 可能出現錯誤 153。正式 GitHub Pages 網址會使用正常網站來源。</p><a class="content-link" href="${escapeHtml(node.dataset.videoUrl)}" target="_blank" rel="noopener noreferrer">前往 YouTube 測試影片</a></div>`;}
  function loadYouTubeApi(){if(window.YT&&window.YT.Player)return Promise.resolve();return new Promise(resolve=>{const old=window.onYouTubeIframeAPIReady;window.onYouTubeIframeAPIReady=()=>{if(typeof old==='function')old();resolve();};if(!document.querySelector('script[data-youtube-api]')){const s=document.createElement('script');s.src='https://www.youtube.com/iframe_api';s.dataset.youtubeApi='1';document.head.appendChild(s);}setTimeout(resolve,6000);});}
  async function mountYoutube(node){await loadYouTubeApi();if(!(window.YT&&window.YT.Player)){showYoutubeError(node,'播放器載入失敗');return;}const cid=node.dataset.contentId;try{const player=new YT.Player(node,{videoId:node.dataset.youtubeId,host:'https://www.youtube.com',playerVars:{rel:0,playsinline:1,origin:location.origin},events:{onReady:e=>{if(state.tracker){const p=ensureContentProgress(cid,'VIDEO'),d=Math.round(n(e.target.getDuration()));if(d>0){p.duration=Math.max(n(p.duration),d);state.tracker.dirty=true;}}},onStateChange:e=>{if(!state.tracker)return;if(e.data===YT.PlayerState.PLAYING)state.tracker.playing.add(cid);else{state.tracker.playing.delete(cid);if(e.data===YT.PlayerState.PAUSED||e.data===YT.PlayerState.ENDED)flushProgress(false);}},onError:()=>showYoutubeError(document.querySelector(`[data-content-id="${CSS.escape(cid)}"] .media-lazy-shell`)||node,'YouTube 無法嵌入此影片')}});state.youtubePlayers.set(cid,player);}catch{showYoutubeError(node,'播放器建立失敗');}}
  function showYoutubeError(target,msg){const container=target.closest?target.closest('.media-lazy-shell')||target:target;const content=container.closest&&container.closest('.video-content');const link=content&&(content.dataset.videoUrl||content.querySelector('[data-video-url]')?.dataset.videoUrl);container.innerHTML=`<div class="media-fallback"><div><strong>${escapeHtml(msg)}</strong><p>可先確認影片是否允許嵌入，或直接前往 YouTube。</p>${link?`<a class="content-link" href="${escapeHtml(link)}" target="_blank" rel="noopener noreferrer">前往 YouTube</a>`:''}</div></div>`;}

  function initLazyPdfVisibility(){const nodes=[...document.querySelectorAll('.pdf-content[data-content-id]')];if(!nodes.length)return;state.pdfObserver=new IntersectionObserver(entries=>entries.forEach(e=>{const id=e.target.dataset.contentId;if(state.tracker){if(e.isIntersecting&&e.intersectionRatio>=.25)state.tracker.visiblePdfs.add(id);else state.tracker.visiblePdfs.delete(id);}if(e.isIntersecting&&!e.target.dataset.loaded){e.target.dataset.loaded='1';loadPdfViewer(e.target);}}),{threshold:[0,.25,.6],rootMargin:'240px 0px'});nodes.forEach(n=>state.pdfObserver.observe(n));}
  function loadPdfJs(){if(window.pdfjsLib)return Promise.resolve(window.pdfjsLib);if(state.pdfJsPromise)return state.pdfJsPromise;state.pdfJsPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=PDFJS_URL;s.onload=()=>{if(window.pdfjsLib){window.pdfjsLib.GlobalWorkerOptions.workerSrc=PDFJS_WORKER;resolve(window.pdfjsLib);}else reject(new Error('PDF.js unavailable'));};s.onerror=reject;document.head.appendChild(s);});return state.pdfJsPromise;}
  async function loadPdfViewer(block){const id=block.dataset.contentId,url=block.dataset.pdfUrl,host=block.querySelector(`[data-pdf-viewer="${CSS.escape(id)}"]`);if(!host)return;if(isDriveUrl(url)){renderPdfIframe(host,url);return;}host.innerHTML='<div class="media-lazy-placeholder"><div><strong>正在載入 PDF…</strong></div></div>';try{const lib=await loadPdfJs(),doc=await lib.getDocument({url}).promise;const cp=state.tracker?ensureContentProgress(id,'PDF'):(state.activeLesson.contentProgress||{})[id]||{};cp.pages=doc.numPages;cp.page=Math.min(Math.max(1,n(cp.page)||1),doc.numPages);cp.maxPage=Math.max(n(cp.maxPage),cp.page);if(state.tracker)state.tracker.dirty=true;host.innerHTML=`<div class="pdf-toolbar"><button class="mini-button" type="button" data-pdf-prev>上一頁</button><span data-pdf-page>${cp.page} / ${doc.numPages}</span><button class="mini-button" type="button" data-pdf-next>下一頁</button></div><div class="pdf-canvas-wrap"><canvas class="pdf-canvas"></canvas></div>`;const canvas=host.querySelector('canvas'),label=host.querySelector('[data-pdf-page]');const render=async()=>{const page=await doc.getPage(cp.page),base=page.getViewport({scale:1}),wrap=host.querySelector('.pdf-canvas-wrap'),target=Math.min(Math.max(300,wrap.clientWidth-24),900),scale=target/base.width,view=page.getViewport({scale});canvas.width=Math.ceil(view.width);canvas.height=Math.ceil(view.height);await page.render({canvasContext:canvas.getContext('2d'),viewport:view}).promise;label.textContent=`${cp.page} / ${doc.numPages}`;cp.maxPage=Math.max(n(cp.maxPage),cp.page);if(state.tracker)state.tracker.dirty=true;};host.querySelector('[data-pdf-prev]').onclick=()=>{if(cp.page>1){cp.page--;render();}};host.querySelector('[data-pdf-next]').onclick=()=>{if(cp.page<doc.numPages){cp.page++;render();}};await render();}catch{renderPdfIframe(host,url);}}
  function renderPdfIframe(host,url){host.innerHTML=`<iframe class="pdf-frame" src="${escapeHtml(drivePreviewUrl(url))}" title="PDF教材" loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe>`;}

  async function confirmPdf(contentId){if(state.previewMode||!state.activeLesson||!state.tracker)return;const p=ensureContentProgress(contentId,'PDF');p.confirmed=true;state.tracker.dirty=true;await flushProgress(false);try{const ps=await window.LearningApi.request('confirmPdf',{lessonId:state.activeLesson.id,contentId,contentProgress:state.tracker.contentProgress},state.token);state.packages=Array.isArray(ps)?ps:state.packages;refreshActiveLesson();startTracker();renderLessonPage();showToast('PDF 已確認');}catch(e){showToast(e.message||'確認失敗');}}

  async function loadQuiz(){if(!state.activeLesson||state.previewMode)return;const area=$('quizArea');area.innerHTML='<div class="loading-list">載入題目…</div>';try{state.quiz=await window.LearningApi.request('getQuiz',{lessonId:state.activeLesson.id},state.token);renderQuiz();}catch(e){area.innerHTML=`<div class="form-message form-message--error">${escapeHtml(e.message||'無法載入測驗')}</div>`;}}
  function renderQuiz(){const area=$('quizArea'),q=state.quiz;if(!area||!q)return;if(!(q.questions||[]).length){area.innerHTML='<div class="content-placeholder">目前沒有測驗題目</div>';return;}area.innerHTML=`<form id="quizForm" class="quiz-form">${q.questions.map((x,i)=>`<fieldset class="quiz-question"><legend>${i+1}. ${escapeHtml(x.question)}</legend>${(x.options||[]).map(o=>`<label class="quiz-option"><input type="radio" name="q_${escapeHtml(x.id)}" value="${escapeHtml(o.key)}" required><span>${escapeHtml(o.key)}. ${escapeHtml(o.text)}</span></label>`).join('')}</fieldset>`).join('')}<button class="primary-button" type="submit">送出測驗</button></form>`;$('quizForm').onsubmit=submitQuiz;}
  async function submitQuiz(e){e.preventDefault();if(!state.activeLesson||!state.quiz)return;const answers={};for(const q of state.quiz.questions||[]){const p=document.querySelector(`input[name="q_${CSS.escape(q.id)}"]:checked`);if(!p){showToast('請完成所有題目');return;}answers[q.id]=p.value;}const b=e.currentTarget.querySelector('button[type="submit"]');b.disabled=true;b.textContent='計算中…';try{const r=await window.LearningApi.request('submitQuiz',{lessonId:state.activeLesson.id,answers},state.token);state.packages=Array.isArray(r.packages)?r.packages:state.packages;refreshActiveLesson();startTracker();renderLessonPage();showToast(`本次 ${r.score} 分${r.passed?'｜通過':'｜未通過'}`);}catch(err){b.disabled=false;b.textContent='送出測驗';showToast(err.message||'測驗提交失敗');}}
  async function closeLesson(){await flushProgress(false);stopTracker(false);$('lessonPage').hidden=true;state.activePackage=null;state.activeLesson=null;state.quiz=null;const wasPreview=state.previewMode;state.previewMode=false;if(wasPreview){$('adminDashboard').hidden=false;renderAdmin();setAdminTab('manage');}else{$('studentDashboard').hidden=false;renderStudent();}}
  async function completeActiveLesson(){const l=state.activeLesson;if(!l||!state.tracker)return;const b=$('completeLessonButton');b.disabled=true;b.textContent='確認中…';try{await flushProgress(false);const ps=await window.LearningApi.request('completeLesson',{lessonId:l.id,contentProgress:state.tracker.contentProgress},state.token);state.packages=Array.isArray(ps)?ps:state.packages;refreshActiveLesson();showToast('子課程已完成');await closeLesson();}catch(e){b.disabled=false;b.textContent='完成此子課程';showToast(e.message||'尚未符合完成條件');}}

  function renderAdmin(){const people=state.adminOverview||[],pkgs=people.reduce((s,p)=>s+(p.packages||[]).length,0),done=people.reduce((s,p)=>s+(p.packages||[]).filter(x=>packageSummary(x).status==='complete').length,0);$('adminSummary').innerHTML=`<article class="summary-card"><span>學員</span><strong>${people.length}</strong></article><article class="summary-card"><span>課程指派</span><strong>${pkgs}</strong></article><article class="summary-card"><span>完成</span><strong>${done}</strong></article>`;renderAdminPeople();renderAdminCourses();renderAdminManage();}
  function matchesSearch(text){const q=$('adminSearch').value.trim().toLowerCase();return !q||String(text||'').toLowerCase().includes(q);}
  function adminLessonMeta(l){return `影片 ${formatSeconds(l.videoSeconds)}｜PDF ${formatSeconds(l.pdfSeconds)}｜測驗 ${l.score==null?'—':l.score+'分'}｜完成 ${formatDateTime(l.completedAt)}`;}
  function renderAdminPeople(){const ps=(state.adminOverview||[]).filter(p=>matchesSearch(`${p.employeeId} ${p.name} ${p.store} ${(p.packages||[]).map(x=>x.title).join(' ')}`));$('adminPeoplePanel').innerHTML=ps.length?ps.map(p=>`<article class="accordion-card"><button class="accordion-toggle" type="button"><span class="accordion-title"><strong>${escapeHtml(p.name)}｜${escapeHtml(p.employeeId)}</strong><span>${escapeHtml(p.area)}｜${escapeHtml(p.store)}</span></span><span class="accordion-arrow">›</span></button><div class="accordion-content" hidden>${(p.packages||[]).map(renderAdminPackage).join('')||'<div class="manage-empty">目前沒有指派課程</div>'}</div></article>`).join(''):'<div class="empty-state"><h3>查無資料</h3></div>';bindAdminAccordions($('adminPeoplePanel'));}
  function renderAdminPackage(pkg){const s=packageSummary(pkg),rows=(pkg.lessons||[]).map(l=>`<div class="admin-lesson-row"><strong>${escapeHtml(l.title)}</strong>${statusTag(l.status)}<span class="admin-lesson-meta">${escapeHtml(adminLessonMeta(l))}</span></div>`).join('');return `<div class="person-package"><button class="person-package__toggle" type="button"><span><strong>${escapeHtml(pkg.title)}</strong><small>${s.done}/${s.total} 完成｜${s.percent}%</small></span>${statusTag(s.status)}</button><div class="person-package__body" hidden>${rows}</div></div>`;}
  function uniquePackagesForAdmin(){const m=new Map();state.adminOverview.forEach(p=>(p.packages||[]).forEach(pkg=>{if(!m.has(pkg.id))m.set(pkg.id,{id:pkg.id,title:pkg.title});}));return [...m.values()];}
  function renderAdminCourses(){const ps=uniquePackagesForAdmin().filter(p=>matchesSearch(`${p.id} ${p.title}`));$('adminCoursesPanel').innerHTML=ps.length?ps.map(info=>{const rows=state.adminOverview.map(p=>{const pkg=(p.packages||[]).find(x=>x.id===info.id);if(!pkg)return '';const s=packageSummary(pkg);return `<div class="person-package"><button class="person-package__toggle" type="button"><span><strong>${escapeHtml(p.name)}｜${escapeHtml(p.employeeId)}</strong><small>${escapeHtml(p.store)}｜${s.done}/${s.total} 完成</small></span>${statusTag(s.status)}</button><div class="person-package__body" hidden>${(pkg.lessons||[]).map(l=>`<div class="admin-lesson-row"><strong>${escapeHtml(l.title)}</strong>${statusTag(l.status)}<span class="admin-lesson-meta">${escapeHtml(adminLessonMeta(l))}</span></div>`).join('')}</div></div>`;}).filter(Boolean).join('');return `<article class="accordion-card"><button class="accordion-toggle" type="button"><span class="accordion-title"><strong>${escapeHtml(info.title)}</strong><span>查看學員狀況</span></span><span class="accordion-arrow">›</span></button><div class="accordion-content" hidden>${rows}</div></article>`;}).join(''):'<div class="empty-state"><h3>查無資料</h3></div>';bindAdminAccordions($('adminCoursesPanel'));}
  function bindAdminAccordions(root){root.querySelectorAll('.accordion-toggle').forEach(b=>b.onclick=()=>{const card=b.closest('.accordion-card'),c=card?.querySelector(':scope > .accordion-content');if(c){c.hidden=!c.hidden;card.classList.toggle('is-open',!c.hidden);}});root.querySelectorAll('.person-package__toggle').forEach(b=>b.onclick=()=>{const x=b.parentElement?.querySelector(':scope > .person-package__body');if(x)x.hidden=!x.hidden;});}

  function catalogPackages(){return Array.isArray(state.adminCatalog?.packages)?state.adminCatalog.packages:[];} function catalogLearners(){return Array.isArray(state.adminCatalog?.learners)?state.adminCatalog.learners:[];} function catalogAssignments(){return Array.isArray(state.adminCatalog?.assignments)?state.adminCatalog.assignments:[];}
  function findCatalogPackage(id){return catalogPackages().find(p=>p.id===id)||null;} function findCatalogLesson(id){for(const p of catalogPackages()){const l=(p.lessons||[]).find(x=>x.id===id);if(l)return l;}return null;}
  function adminEnabledText(v){return v===false?'停用':'啟用';}
  function ruleText(l){const a=[];if(l.videoPassPercent!=null)a.push(`影片 ${l.videoPassPercent}%`);if(l.pdfConfirmRequired)a.push('PDF確認');if(l.quizPassScore!=null)a.push(`測驗 ${l.quizPassScore}分`);return a.join('＋')||'完成確認';}
  function publishBadge(p){const s=p.publishState||'草稿',c=s==='已發布'?'manage-status--published':s==='封存'?'manage-status--archived':'manage-status--draft';return `<span class="manage-status ${c}">${escapeHtml(s)}</span>`;}
  function validateCatalogPackage(p){const errors=[];const ls=(p.lessons||[]).filter(l=>l.enabled!==false);if(!ls.length)errors.push('至少需要 1 個啟用中的子課程');ls.forEach(l=>{const cs=(l.contents||[]).filter(c=>c.enabled!==false),types=new Set(cs.map(c=>c.type));if(!cs.length)errors.push(`${l.title}：尚未建立教材`);if(l.videoPassPercent!=null&&!cs.some(c=>c.type==='VIDEO'&&youtubeId(c.url)))errors.push(`${l.title}：設定影片通過條件但沒有有效 YouTube`);if(l.pdfConfirmRequired&&!cs.some(c=>c.type==='PDF'&&c.url))errors.push(`${l.title}：設定 PDF 確認但沒有 PDF`);if(l.quizPassScore!=null&&!(l.questions||[]).some(q=>q.enabled!==false))errors.push(`${l.title}：設定測驗分數但沒有題目`);});return errors;}
  function renderAdminManage(){const packages=catalogPackages(),assignments=catalogAssignments().filter(a=>a.enabled!==false),lessonCount=packages.reduce((s,p)=>s+(p.lessons||[]).length,0);$('adminCatalogSummary').innerHTML=`<article class="summary-card"><span>母課程</span><strong>${packages.length}</strong></article><article class="summary-card"><span>子課程</span><strong>${lessonCount}</strong></article><article class="summary-card"><span>有效指派</span><strong>${assignments.length}</strong></article>`;$('adminCatalogList').innerHTML=packages.length?packages.map(p=>{const errors=validateCatalogPackage(p),activeAssign=assignments.filter(a=>a.packageId===p.id).length,lessons=(p.lessons||[]).map(l=>{const contents=(l.contents||[]).map(c=>`<div class="manage-content"><span><strong>${escapeHtml(c.title)}</strong><small>${escapeHtml(c.type)}｜${adminEnabledText(c.enabled)}</small></span><button class="mini-button" type="button" data-edit-content="${escapeHtml(c.id)}">編輯</button></div>`).join(''),questions=(l.questions||[]).map(q=>`<div class="manage-content manage-question"><span><strong>${escapeHtml(q.question)}</strong><small>答案 ${escapeHtml(q.correctAnswer)}｜${q.points} 分｜${adminEnabledText(q.enabled)}</small></span><button class="mini-button" type="button" data-edit-question="${escapeHtml(q.id)}" data-lesson-id="${escapeHtml(l.id)}">編輯</button></div>`).join('');return `<div class="manage-row"><div class="manage-row__top"><div><strong>${escapeHtml(l.title)}</strong><div class="manage-row__meta">${l.required?'必修':'選修'}｜${escapeHtml(ruleText(l))}｜${adminEnabledText(l.enabled)}</div></div><div class="manage-row__actions"><button class="mini-button" type="button" data-edit-lesson="${escapeHtml(l.id)}">編輯</button><button class="mini-button" type="button" data-add-content="${escapeHtml(l.id)}">＋教材</button><button class="mini-button" type="button" data-add-question="${escapeHtml(l.id)}">＋題目</button></div></div><div class="manage-content-list">${contents}${questions}${!contents&&!questions?'<div class="manage-empty">尚未建立教材</div>':''}</div></div>`;}).join('');return `<article class="manage-card"><div class="manage-card__head"><div class="manage-card__title"><strong>${escapeHtml(p.title)}</strong><small>${escapeHtml(p.description||'')}｜${adminEnabledText(p.enabled)}｜已指派 ${activeAssign} 人</small><div style="margin-top:7px">${publishBadge(p)}</div>${errors.length?`<div class="manage-warning">${escapeHtml(errors.slice(0,3).join('；'))}${errors.length>3?'…':''}</div>`:''}</div><div class="manage-card__actions"><button class="mini-button" type="button" data-toggle-manage="${escapeHtml(p.id)}">展開</button><button class="mini-button" type="button" data-preview-package="${escapeHtml(p.id)}">預覽</button><button class="mini-button" type="button" data-edit-package="${escapeHtml(p.id)}">編輯</button><button class="mini-button" type="button" data-add-lesson="${escapeHtml(p.id)}">＋子課程</button><button class="mini-button" type="button" data-assign-package="${escapeHtml(p.id)}">批次指派</button>${p.publishState==='已發布'?`<button class="mini-button" type="button" data-draft-package="${escapeHtml(p.id)}">轉草稿</button>`:`<button class="mini-button" type="button" data-publish-package="${escapeHtml(p.id)}">發布</button>`}<button class="mini-button mini-button--danger" type="button" data-delete-package="${escapeHtml(p.id)}">刪除／封存</button></div></div><div class="manage-card__body" data-manage-body="${escapeHtml(p.id)}" hidden>${lessons||'<div class="manage-empty">尚未建立子課程</div>'}</div></article>`;}).join(''):'<div class="empty-state"><h3>目前沒有母課程</h3></div>';bindAdminManageEvents();}
  function bindAdminManageEvents(){document.querySelectorAll('[data-toggle-manage]').forEach(b=>b.onclick=()=>{const x=document.querySelector(`[data-manage-body="${CSS.escape(b.dataset.toggleManage)}"]`);if(x){x.hidden=!x.hidden;b.textContent=x.hidden?'展開':'收合';}});document.querySelectorAll('[data-preview-package]').forEach(b=>b.onclick=()=>openAdminPreview(findCatalogPackage(b.dataset.previewPackage)));document.querySelectorAll('[data-edit-package]').forEach(b=>b.onclick=()=>openPackageEditor(findCatalogPackage(b.dataset.editPackage)));document.querySelectorAll('[data-add-lesson]').forEach(b=>b.onclick=()=>openLessonEditor(null,b.dataset.addLesson));document.querySelectorAll('[data-edit-lesson]').forEach(b=>b.onclick=()=>openLessonEditor(findCatalogLesson(b.dataset.editLesson)));document.querySelectorAll('[data-add-content]').forEach(b=>b.onclick=()=>openContentEditor(null,b.dataset.addContent));document.querySelectorAll('[data-edit-content]').forEach(b=>b.onclick=()=>{const id=b.dataset.editContent;for(const p of catalogPackages())for(const l of p.lessons||[]){const c=(l.contents||[]).find(x=>x.id===id);if(c)return openContentEditor(c,c.lessonId);}});document.querySelectorAll('[data-add-question]').forEach(b=>b.onclick=()=>openQuestionEditor(null,b.dataset.addQuestion));document.querySelectorAll('[data-edit-question]').forEach(b=>b.onclick=()=>{const l=findCatalogLesson(b.dataset.lessonId),q=l&&(l.questions||[]).find(x=>x.id===b.dataset.editQuestion);if(q)openQuestionEditor(q,l.id);});document.querySelectorAll('[data-assign-package]').forEach(b=>b.onclick=()=>openAssignmentEditor(findCatalogPackage(b.dataset.assignPackage)));document.querySelectorAll('[data-publish-package]').forEach(b=>b.onclick=()=>changePublishState(b.dataset.publishPackage,'已發布'));document.querySelectorAll('[data-draft-package]').forEach(b=>b.onclick=()=>changePublishState(b.dataset.draftPackage,'草稿'));document.querySelectorAll('[data-delete-package]').forEach(b=>b.onclick=()=>safeDeletePackage(b.dataset.deletePackage));}
  async function changePublishState(id,publishState){try{const d=await saveAdminAction('setPackageState',{id,publishState});showToast(d.message||`已改為${publishState}`);}catch(e){showToast(e.message||'操作失敗');}}
  async function safeDeletePackage(id){const p=findCatalogPackage(id);if(!p)return;if(!confirm(`確定處理「${p.title}」？\n有學習/指派紀錄時會改為封存，不會破壞歷史資料。`))return;try{const d=await saveAdminAction('deletePackage',{id});showToast(d.message||'已處理');}catch(e){showToast(e.message||'操作失敗');}}

  function showAdminEditor(title,html){$('adminEditorTitle').textContent=title;$('adminEditorBody').innerHTML=html;$('adminEditorOverlay').hidden=false;document.body.classList.add('is-locked');}
  function closeAdminEditor(){$('adminEditorOverlay').hidden=true;$('adminEditorBody').innerHTML='';document.body.classList.remove('is-locked');}
  function yesNoSelect(v){return `<option value="true" ${v!==false?'selected':''}>是</option><option value="false" ${v===false?'selected':''}>否</option>`;}
  function field(label,id,value='',type='text',extra=''){return `<label class="field-group"><span>${label}</span><input id="${id}" type="${type}" value="${escapeHtml(value??'')}" ${extra}></label>`;}
  function openPackageEditor(pkg){pkg=pkg||{title:'',description:'',enabled:true,sort:catalogPackages().length+1,publishState:'草稿'};showAdminEditor(pkg.id?'編輯母課程':'新增母課程',`<form id="adminEditForm" class="admin-form" data-admin-form="package"><input type="hidden" id="editId" value="${escapeHtml(pkg.id||'')}"><input type="hidden" id="editPublishState" value="${escapeHtml(pkg.publishState||'草稿')}"><div class="form-grid">${field('母課程名稱','editTitle',pkg.title,'text','required')}${field('排序','editSort',pkg.sort||1,'number','min="1" required')}<label class="field-group field-group--wide"><span>簡短說明</span><textarea id="editDescription">${escapeHtml(pkg.description||'')}</textarea></label><label class="field-group"><span>啟用</span><select id="editEnabled">${yesNoSelect(pkg.enabled)}</select></label></div><p class="form-hint">新增後預設為草稿，完成內容後再從課程卡按「發布」。</p><div class="form-actions"><button class="secondary-button" type="button" data-cancel-editor>取消</button><button class="primary-button" type="submit">儲存</button></div></form>`);bindEditorForm();}
  function openLessonEditor(l,packageId){l=l||{packageId,title:'',required:true,enabled:true,sort:(findCatalogPackage(packageId)?.lessons||[]).length+1,videoPassPercent:null,pdfConfirmRequired:false,quizPassScore:null};showAdminEditor(l.id?'編輯子課程':'新增子課程',`<form id="adminEditForm" class="admin-form" data-admin-form="lesson"><input type="hidden" id="editId" value="${escapeHtml(l.id||'')}"><input type="hidden" id="editPackageId" value="${escapeHtml(l.packageId||packageId||'')}"><div class="form-grid">${field('子課程名稱','editTitle',l.title,'text','required')}${field('排序','editSort',l.sort||1,'number','min="1" required')}<label class="field-group"><span>必修</span><select id="editRequired">${yesNoSelect(l.required)}</select></label><label class="field-group"><span>啟用</span><select id="editEnabled">${yesNoSelect(l.enabled)}</select></label>${field('影片最低完成率 %','editVideo',l.videoPassPercent??'','number','min="1" max="100"')}${field('測驗及格分數','editQuiz',l.quizPassScore??'','number','min="0" max="100"')}<label class="field-group"><span>PDF需完成確認</span><select id="editPdf">${yesNoSelect(l.pdfConfirmRequired)}</select></label></div><div class="form-actions"><button class="secondary-button" type="button" data-cancel-editor>取消</button><button class="primary-button" type="submit">儲存</button></div></form>`);bindEditorForm();}
  function openContentEditor(c,lessonId){c=c||{lessonId,type:'VIDEO',title:'',url:'',text:'',sort:(findCatalogLesson(lessonId)?.contents||[]).length+1,enabled:true};showAdminEditor(c.id?'編輯教材':'新增教材',`<form id="adminEditForm" class="admin-form" data-admin-form="content"><input type="hidden" id="editId" value="${escapeHtml(c.id||'')}"><input type="hidden" id="editLessonId" value="${escapeHtml(c.lessonId||lessonId||'')}"><div class="form-grid"><label class="field-group"><span>教材類型</span><select id="editType"><option value="VIDEO" ${c.type==='VIDEO'?'selected':''}>YouTube影片</option><option value="PDF" ${c.type==='PDF'?'selected':''}>PDF</option><option value="TEXT" ${c.type==='TEXT'?'selected':''}>文字</option><option value="QUIZ" ${c.type==='QUIZ'?'selected':''}>測驗</option></select></label>${field('排序','editSort',c.sort||1,'number','min="1" required')}${field('教材標題','editTitle',c.title,'text','required')}<label class="field-group"><span>啟用</span><select id="editEnabled">${yesNoSelect(c.enabled)}</select></label><label class="field-group field-group--wide"><span>YouTube／PDF 連結</span><input id="editUrl" type="url" value="${escapeHtml(c.url||'')}" placeholder="https://..."></label><label class="field-group field-group--wide"><span>文字教材內容</span><textarea id="editText">${escapeHtml(c.text||'')}</textarea></label></div><div class="form-actions"><button id="testContentLinkButton" class="secondary-button" type="button">測試連結</button><button class="secondary-button" type="button" data-cancel-editor>取消</button><button class="primary-button" type="submit">儲存</button></div></form>`);bindEditorForm();$('testContentLinkButton').onclick=()=>{const type=$('editType').value,url=$('editUrl').value.trim();if(!['VIDEO','PDF'].includes(type)){showToast('此教材類型不需要連結');return;}if(!/^https?:\/\//i.test(url)){showToast('請先輸入有效網址');return;}if(type==='VIDEO'&&!youtubeId(url)){showToast('YouTube 網址格式不正確');return;}window.open(url,'_blank','noopener');};}
  function openQuestionEditor(q,lessonId){q=q||{lessonId,question:'',optionA:'',optionB:'',optionC:'',optionD:'',correctAnswer:'A',points:1,enabled:true};showAdminEditor(q.id?'編輯測驗題目':'新增測驗題目',`<form id="adminEditForm" class="admin-form" data-admin-form="question"><input type="hidden" id="editId" value="${escapeHtml(q.id||'')}"><input type="hidden" id="editLessonId" value="${escapeHtml(q.lessonId||lessonId||'')}"><div class="form-grid"><label class="field-group field-group--wide"><span>題目</span><textarea id="editQuestion" required>${escapeHtml(q.question||'')}</textarea></label>${field('選項 A','editA',q.optionA,'text','required')}${field('選項 B','editB',q.optionB,'text','required')}${field('選項 C','editC',q.optionC)}${field('選項 D','editD',q.optionD)}<label class="field-group"><span>正確答案</span><select id="editAnswer">${['A','B','C','D'].map(x=>`<option ${q.correctAnswer===x?'selected':''}>${x}</option>`).join('')}</select></label>${field('題目分數','editPoints',q.points||1,'number','min="1" required')}<label class="field-group"><span>啟用</span><select id="editEnabled">${yesNoSelect(q.enabled)}</select></label></div><div class="form-actions"><button class="secondary-button" type="button" data-cancel-editor>取消</button><button class="primary-button" type="submit">儲存</button></div></form>`);bindEditorForm();}
  function openAssignmentEditor(pkg){if(!pkg)return;const active=catalogAssignments().filter(a=>a.packageId===pkg.id&&a.enabled!==false),activeIds=new Set(active.map(a=>a.employeeId)),map=new Map(catalogLearners().map(l=>[l.employeeId,l]));const rows=active.map(a=>{const l=map.get(a.employeeId)||{name:a.employeeId,store:''};return `<div class="assignment-row"><span><strong>${escapeHtml(l.name)}｜${escapeHtml(a.employeeId)}</strong><small>${escapeHtml(l.store||'')}${a.dueAt?`｜截止 ${escapeHtml(a.dueAt)}`:''}</small></span><button class="mini-button mini-button--danger" type="button" data-disable-assignment="${escapeHtml(a.id)}" data-employee-id="${escapeHtml(a.employeeId)}">取消指派</button></div>`;}).join('');showAdminEditor(`批次指派｜${pkg.title}`,`<form id="adminEditForm" class="admin-form" data-admin-form="assignment"><input type="hidden" id="editPackageId" value="${escapeHtml(pkg.id)}"><label class="field-group"><span>選擇要新增／重新啟用的學員</span><div class="learner-checklist">${catalogLearners().map(l=>`<label class="learner-check"><input type="checkbox" name="assignLearner" value="${escapeHtml(l.employeeId)}" ${activeIds.has(l.employeeId)?'checked':''}><span><strong>${escapeHtml(l.name)}｜${escapeHtml(l.employeeId)}</strong><small>${escapeHtml(l.store)}</small></span></label>`).join('')}</div></label>${field('截止日期','editDue','', 'date')}<button class="primary-button" type="submit">儲存批次指派</button></form><div class="assignment-list">${rows||'<div class="manage-empty">目前沒有指派學員</div>'}</div>`);bindEditorForm();document.querySelectorAll('[data-disable-assignment]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await saveAdminAction('saveAssignment',{id:b.dataset.disableAssignment,employeeId:b.dataset.employeeId,packageId:pkg.id,enabled:false});closeAdminEditor();openAssignmentEditor(findCatalogPackage(pkg.id));showToast('已取消指派');}catch(e){b.disabled=false;showToast(e.message||'操作失敗');}});}
  function bindEditorForm(){document.querySelectorAll('[data-cancel-editor]').forEach(b=>b.onclick=closeAdminEditor);const f=$('adminEditForm');if(f)f.onsubmit=submitAdminEditor;}
  function boolValue(id){return $(id)&&$(id).value==='true';} function optionalNumber(id){const v=$(id)?.value.trim()||'';return v===''?null:Number(v);}
  async function saveAdminAction(action,payload){const d=await window.LearningApi.request(action,payload,state.token);state.adminOverview=Array.isArray(d.overview)?d.overview:state.adminOverview;state.adminCatalog=d.catalog||state.adminCatalog;if(d.user)state.user=d.user;renderAdmin();return d;}
  async function submitAdminEditor(e){e.preventDefault();const f=e.currentTarget,k=f.dataset.adminForm,b=f.querySelector('button[type="submit"]');b.disabled=true;try{let action,payload;if(k==='package'){action='savePackage';payload={id:$('editId').value,title:$('editTitle').value,description:$('editDescription').value,sort:Number($('editSort').value),enabled:boolValue('editEnabled'),publishState:$('editPublishState').value};}else if(k==='lesson'){action='saveLesson';payload={id:$('editId').value,packageId:$('editPackageId').value,title:$('editTitle').value,sort:Number($('editSort').value),required:boolValue('editRequired'),enabled:boolValue('editEnabled'),videoPassPercent:optionalNumber('editVideo'),pdfConfirmRequired:boolValue('editPdf'),quizPassScore:optionalNumber('editQuiz')};}else if(k==='content'){action='saveContent';payload={id:$('editId').value,lessonId:$('editLessonId').value,type:$('editType').value,title:$('editTitle').value,url:$('editUrl').value,text:$('editText').value,sort:Number($('editSort').value),enabled:boolValue('editEnabled')};}else if(k==='question'){action='saveQuestion';payload={id:$('editId').value,lessonId:$('editLessonId').value,question:$('editQuestion').value,optionA:$('editA').value,optionB:$('editB').value,optionC:$('editC').value,optionD:$('editD').value,correctAnswer:$('editAnswer').value,points:Number($('editPoints').value),enabled:boolValue('editEnabled')};}else if(k==='assignment'){action='saveAssignmentsBatch';payload={employeeIds:[...document.querySelectorAll('input[name="assignLearner"]:checked')].map(x=>x.value),packageId:$('editPackageId').value,dueAt:$('editDue').value};}else return;await saveAdminAction(action,payload);closeAdminEditor();showToast('已儲存');}catch(err){b.disabled=false;showToast(err.message||'儲存失敗');}}

  async function exportProgress(){try{const rows=await window.LearningApi.request('exportProgress',{},state.token);if(!Array.isArray(rows)||!rows.length){showToast('目前沒有可匯出的紀錄');return;}const headers=Object.keys(rows[0]),esc=v=>`"${String(v??'').replace(/"/g,'""')}"`,csv='\ufeff'+[headers.map(esc).join(','),...rows.map(r=>headers.map(h=>esc(r[h])).join(','))].join('\r\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`learning_progress_${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){showToast(e.message||'匯出失敗');}}
  function setStudentTab(tab){document.querySelectorAll('[data-student-tab]').forEach(b=>b.classList.toggle('is-active',b.dataset.studentTab===tab));$('studentCoursesPanel').hidden=tab!=='courses';$('studentRecordsPanel').hidden=tab!=='records';}
  function setAdminTab(tab){state.adminTab=tab;document.querySelectorAll('[data-admin-tab]').forEach(b=>b.classList.toggle('is-active',b.dataset.adminTab===tab));const tracking=tab==='people'||tab==='courses';$('adminTrackingPanel').hidden=!tracking;$('adminManagePanel').hidden=tab!=='manage';$('adminPeoplePanel').hidden=tab!=='people';$('adminCoursesPanel').hidden=tab!=='courses';if(tab==='manage')renderAdminManage();}
  async function logout(){if(state.activeLesson)await closeLesson();try{if(state.token)await window.LearningApi.request('logout',{},state.token);}catch{}state.token='';state.user=null;state.packages=[];state.adminOverview=[];state.adminCatalog={packages:[],learners:[],assignments:[]};clearSession();$('dashboardView').hidden=true;$('studentDashboard').hidden=true;$('adminDashboard').hidden=true;$('lessonPage').hidden=true;$('loginView').hidden=false;$('password').value='';}

  $('loginForm').addEventListener('submit',async e=>{e.preventDefault();$('loginMessage').hidden=true;setLoginLoading(true);try{await login($('employeeId').value.trim(),$('password').value.trim());}catch(err){state.token='';clearSession();showLoginError(err.message||'登入失敗');}finally{setLoginLoading(false);}});
  $('togglePassword').onclick=()=>{const i=$('password');i.type=i.type==='password'?'text':'password';$('togglePassword').textContent=i.type==='password'?'顯示':'隱藏';};
  $('logoutButton').onclick=logout;$('backLessonButton').onclick=closeLesson;$('completeLessonButton').onclick=completeActiveLesson;$('newPackageButton').onclick=()=>openPackageEditor(null);$('exportProgressButton').onclick=exportProgress;$('closeAdminEditorButton').onclick=closeAdminEditor;$('adminEditorOverlay').onclick=e=>{if(e.target===$('adminEditorOverlay'))closeAdminEditor();};document.querySelectorAll('[data-student-tab]').forEach(b=>b.onclick=()=>setStudentTab(b.dataset.studentTab));document.querySelectorAll('[data-admin-tab]').forEach(b=>b.onclick=()=>setAdminTab(b.dataset.adminTab));$('adminSearch').oninput=()=>{renderAdminPeople();renderAdminCourses();};
  window.addEventListener('beforeunload',()=>{if(state.tracker&&state.tracker.dirty)flushProgress(false);});

  (async()=>{await checkHealth();const restored=await restoreSession();if(!restored){$('loginView').hidden=false;$('dashboardView').hidden=true;}})();
})();
